const D = { bars:.12, energy:.6, hue:30, speed:1, density:.5, scale:1, x:.5, y:.5, style:'sepia', act:'reel', seed:0, tint:.5 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const nz=x=>{const i=Math.floor(x),f=x-i,a=fr(i),b=fr(i+1);const t=f*f*(3-2*f);return a+(b-a)*t;};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const style=P.style, act=P.act;
const spd=Math.max(0.05,P.speed);
const t=K.t*spd;
const en=clp(P.energy,0,1)*(0.6+0.4*K.intensity);
const tn=clp(P.tint,0,1);
const dens=clp(P.density,0,1);

// ---- cached grain tiles (seed-keyed) ----
const gw=200, gh=120;
if(!S.grain || S.gk!==P.seed){
  if(S.grain){ for(const g of S.grain){ try{g.remove();}catch(e){} } }
  S.gk=P.seed; S.grain=[];
  for(let ti=0;ti<4;ti++){ const gb=createGraphics(gw,gh); gb.colorMode(HSB,360,100,100,100); gb.loadPixels(); const pp=gb.pixels;
    for(let i=0;i<gw*gh;i++){ const n=fr(i*1.71+ti*911.3+7); const v=128+(n-0.5)*235; pp[4*i]=v;pp[4*i+1]=v;pp[4*i+2]=v;pp[4*i+3]=255; }
    gb.updatePixels(); S.grain.push(gb); }
}
// ---- cached warm burn glow sprite + vignette (size-keyed) ----
if(!S.glow || S.vk!==W+'x'+Hh){
  if(S.glow){try{S.glow.remove();}catch(e){}} if(S.vig){try{S.vig.remove();}catch(e){}}
  S.vk=W+'x'+Hh;
  const gh2=Math.round(u*0.17);
  const gl=createGraphics(W,gh2); gl.colorMode(HSB,360,100,100,100); gl.noStroke();
  const gc=gl.drawingContext, lg=gc.createLinearGradient(0,0,0,gh2);
  lg.addColorStop(0,'rgba(255,150,40,0.9)'); lg.addColorStop(0.5,'rgba(255,110,20,0.28)'); lg.addColorStop(1,'rgba(255,90,10,0)');
  gc.fillStyle=lg; gc.fillRect(0,0,W,gh2); S.glow=gl; S.glowH=gh2;
  const vg=createGraphics(W,Hh); vg.colorMode(HSB,360,100,100,100);
  const vc=vg.drawingContext, rg=vc.createRadialGradient(W/2,Hh/2,u*0.28,W/2,Hh/2,u*0.8);
  rg.addColorStop(0,'rgba(0,0,0,0)'); rg.addColorStop(1,'rgba(0,0,0,0.5)');
  vc.fillStyle=rg; vc.fillRect(0,0,W,Hh); S.vig=vg;
}

noStroke();
// ---- 1. film-stock tint wash (bars will cover the edges) ----
if(style==='sepia'){
  blendMode(MULTIPLY); fill(md(H,360),40,88, 26*tn+8); rect(0,0,W,Hh);
  blendMode(ADD); fill(md(H+6,360),55,100, 8*tn); rect(0,0,W,Hh);
} else if(style==='noir'){
  blendMode(MULTIPLY); fill(0,0,58, 40*tn+10); rect(0,0,W,Hh);
  blendMode(MULTIPLY); fill(220,10,40, 14*tn); rect(0,0,W,Hh);
} else if(style==='technicolor'){
  blendMode(SCREEN); fill(200,70,60, 12*tn); rect(0,0,W,Hh*0.55);
  fill(md(H,360),75,66, 14*tn); rect(0,Hh*0.45,W,Hh*0.55);
} else if(style==='bleach'){
  blendMode(SCREEN); fill(40,8,90, 20*tn); rect(0,0,W,Hh);
  blendMode(MULTIPLY); fill(0,0,70, 16*tn); rect(0,0,W,Hh);
} else if(style==='infrared'){
  blendMode(MULTIPLY); fill(320,60,80, 22*tn); rect(0,0,W,Hh*0.5);
  fill(180,70,80, 22*tn); rect(0,Hh*0.5,W,Hh*0.5);
  blendMode(ADD); fill(300,80,100, 6*tn); rect(0,0,W,Hh);
}
blendMode(BLEND);

// ---- 2. animated film grain (carries motion even on flat input) ----
const gi=Math.floor(t*22)%4;
const gmul=(style==='noir'||style==='bleach')?1.5:1;
const ga=clp(lrp(6,60,en)*(0.45+0.55*dens)*gmul, 0, 75);
push(); blendMode(OVERLAY); tint(0,0,100, ga);
const jx=(nz(t*6)-0.5)*u*0.03, jy=(nz(t*6+40)-0.5)*u*0.03;
image(S.grain[gi], jx, jy, W+Math.abs(jx)*2, Hh+Math.abs(jy)*2);
pop(); noTint();

// ---- 3. letterbox bars (clean black, subtle weave) ----
const barH=clp(P.bars,0,0.32)*Hh + Math.sin(t*6.3)*u*0.0018;
blendMode(BLEND); fill(0,0,0);
rect(0,0,W,Math.max(0,barH)); rect(0,Hh-Math.max(0,barH),W,Math.max(0,barH)+1);

// ---- 4. warm burn glow flickering at inner bar edges ----
const flick=0.35+0.65*nz(t*9)+0.4*A.bass;
push(); blendMode(ADD); tint(0,0,100, clp(flick*lrp(20,80,en),0,90));
image(S.glow, 0, barH, W, S.glowH);
push(); scale(1,-1); image(S.glow, 0, -(Hh-barH), W, S.glowH); pop();
pop(); noTint();

// ---- 5. light leak (act:leak) — warm blob sweeping across, partial ----
if(act==='leak'){
  const lx=md(t*0.13,1)*W*1.3-W*0.15, ly=Hh*(0.3+0.4*nz(t*0.2));
  push(); blendMode(ADD); noStroke();
  drawingContext.shadowBlur=u*0.12; drawingContext.shadowColor='rgba(255,140,40,0.9)';
  fill(md(H+4,360),70,100, clp(28*en*(0.6+0.4*nz(t*0.5)),0,40)); circle(lx,ly,u*0.3);
  drawingContext.shadowBlur=0; pop();
}
// ---- 5b. cigarette-burn reel cue marks (act:reel) top-right ----
if(act==='reel'){
  const cue=md(t,8);
  if(cue<0.28){ const a=Math.sin(cue/0.28*Math.PI); push(); blendMode(ADD); noFill();
    stroke(40,25,100, a*70); strokeWeight(Math.max(1.5,u*0.005));
    const cx=W*0.86,cy=barH+u*0.09; circle(cx,cy,u*0.055); circle(cx,cy,u*0.028); pop(); }
}
// ---- 5c. scratches accumulating (act:decay) ----
if(act==='decay'){
  const ns=Math.round(1+K.section*0.9*(0.4+dens)*3);
  push(); blendMode(SCREEN);
  for(let i=0;i<ns;i++){ const seedi=i*7+Math.floor(t*1.4)*13; const x=fr(seedi)*W + Math.sin(t*3+i)*u*0.004;
    stroke(30,12,100, lrp(12,34,fr(seedi+1))); strokeWeight(Math.max(1,u*0.0016)); line(x,barH,x,Hh-barH); }
  pop();
}

// ---- 6. vignette + subtle exposure breathe ----
blendMode(MULTIPLY); image(S.vig,0,0);
blendMode(BLEND);
const expo=(0.5-0.5*nz(t*4))*lrp(0,10,en);
fill(0,0,0, expo); rect(0,barH,W,Hh-2*barH);

blendMode(BLEND); noTint(); drawingContext.shadowBlur=0;
